if(r.c==="wiz")return O("rocket","Asistente de bienvenida","Repite los pasos: idioma, cuenta, RAM, tema y primera versión",`<button class="btn" id="wzb">Abrir</button>`);
if(r.c==="dsc")return O("users","Estado de Discord",`<span id="dscm">${dlabel()}</span>`,"");
if(r.c==="web")return O("globe","Web de descarga","Descarga Nova Launcher y mira las novedades",`<button class="btn" id="webl">Abrir la web</button>`);
if(r.c==="lnk")return O("rocket","Acceso directo del escritorio","Crea el icono de Nova Launcher en tu escritorio",`<button class="btn" id="lnk">Crear acceso directo</button>`);
